import json
task = json.load(open('task.json'))
parts = {p['index']: p for p in task['parts']}
N=len(parts)
def box(p):
    s=p['size_m']; pos=p['target_position']
    return (pos[0]-s[0]/2,pos[0]+s[0]/2,pos[1]-s[1]/2,pos[1]+s[1]/2,pos[2]-s[2]/2,pos[2]+s[2]/2)
data={i:box(p) for i,p in parts.items()}
def overlap(a,b):
    # a,b = (xmin,xmax,ymin,ymax,bot,top)
    ox = min(a[1],b[1])-max(a[0],b[0])
    oy = min(a[3],b[3])-max(a[2],b[2])
    return ox>1e-4 and oy>1e-4, ox*oy
supports={}
for B in parts:
    xb,xX,yb,yT = data[B][:4], data[B][4], data[B][5]
    bot=data[B][4]
    cands=[]
    if abs(bot)<1e-6:
        cands.append('table')
    for A in parts:
        if A==B: continue
        topA=data[A][5]
        if abs(topA-bot)<1e-6 and overlap(data[A],data[B]):
            cands.append(A)
    supports[B]=cands
for B in sorted(parts):
    print(f"{B:2d} bot={data[B][4]:.3f} <- {supports[B]}")

